schema:
CREATE TABLE ACTORDIRECTOR (
    TIMESTAMP INT,
    ACTOR_ID INT,
    DIRECTOR_ID INT,
    PRIMARY KEY (TIMESTAMP)
);

CREATE TABLE CUSTOMERS (
    ID INT,
    NAME VARCHAR(255),
    PRIMARY KEY (ID)
);

CREATE TABLE ORDERS (
    ID INT,
    CUSTOMERID VARCHAR(255),
    PRIMARY KEY (ID),
    FOREIGN KEY (CUSTOMERID) REFERENCES CUSTOMERS(ID)
);

CREATE TABLE FOLLOW (
    FOLLOWEE VARCHAR(255),
    FOLLOWER VARCHAR(255),
    PRIMARY KEY (FOLLOWEE, FOLLOWER),
    CHECK (FOLLOWEE <> FOLLOWER)
);

counterexample:
INSERT INTO FOLLOW (FOLLOWEE, FOLLOWER) VALUES ('Alice', 'Bob');
INSERT INTO FOLLOW (FOLLOWEE, FOLLOWER) VALUES ('Alice', 'Charlie');
INSERT INTO FOLLOW (FOLLOWEE, FOLLOWER) VALUES ('Bob', 'Alice');
INSERT INTO FOLLOW (FOLLOWEE, FOLLOWER) VALUES ('Bob', 'David');
INSERT INTO FOLLOW (FOLLOWEE, FOLLOWER) VALUES ('Charlie', 'Alice');

